// Simulates 5 marketing form submissions with common data quality flaws
return [
  {
    json: {
      leadId: "LD-001",
      name: " Sarah Connor ",
      email: "SARAH.CONNOR@SKYNET-RESIST.ORG ",
      phone: "(555) 234-5678",
      company: "Tech Resistance",
      notes: "Valid lead with US phone formatting"
    }
  },
  {
    json: {
      leadId: "LD-002",
      name: "Bad Email User",
      email: "invalid-email@@nowhere",
      phone: "+1 555 987 6543",
      company: "Test Corp",
      notes: "Malformed email"
    }
  },
  {
    json: {
      leadId: "LD-003",
      name: "Spam Bot",
      email: "freebie@mailinator.com",
      phone: "555-111-2222",
      company: "Spam Co",
      notes: "Disposable domain"
    }
  },
  {
    json: {
      leadId: "LD-004",
      name: "Sarah Connor (Duplicate Submission)",
      email: "sarah.connor@skynet-resist.org",
      phone: "+1 (555) 234-5678",
      company: "Tech Resistance Inc",
      notes: "Duplicate of LD-001 with minor whitespace variance"
    }
  },
  {
    json: {
      leadId: "LD-005",
      name: "Marcus Wright",
      email: "marcus@cyberdyne.com",
      phone: "+44 20 7946 0919",
      company: "Cyberdyne Systems",
      notes: "Valid international UK lead"
    }
  }
];

const item = $input.item.json;

// 1. Clean and lowercase email
const cleanEmail = String(item.email || '').trim().toLowerCase();

// 2. Clean phone number and standardize to E.164
let rawPhone = String(item.phone || '').trim();
let cleanPhone = rawPhone.replace(/[^\d+]/g, '');

// Prepend +1 if 10-digit US number without country code
if (/^\d{10}$/.test(cleanPhone)) {
  cleanPhone = '+1' + cleanPhone;
} else if (/^1\d{10}$/.test(cleanPhone)) {
  cleanPhone = '+' + cleanPhone;
}

// 3. Trim name and company
const cleanName = String(item.name || '').trim();
const cleanCompany = String(item.company || '').trim();

return {
  json: {
    leadId: item.leadId,
    name: cleanName,
    email: cleanEmail,
    phone: cleanPhone,
    company: cleanCompany,
    rawNotes: item.notes
  }
};

const item = $input.item.json;
const errors = [];

// 1. Email format check
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(item.email)) {
  errors.push("INVALID_EMAIL_SYNTAX");
}

// 2. Disposable email domain check
const disposableDomains = ['mailinator.com', 'tempmail.com', '10minutemail.com', 'guerrillamail.com', 'trashmail.com'];
const emailDomain = item.email.split('@')[1] || '';
if (disposableDomains.includes(emailDomain)) {
  errors.push("DISPOSABLE_EMAIL_DOMAIN_BLOCKED");
}

// 3. Phone format check (E.164: + followed by 10 to 15 digits)
const e164Regex = /^\+[1-9]\d{9,14}$/;
if (!e164Regex.test(item.phone)) {
  errors.push("INVALID_E164_PHONE");
}

// 4. Name check
if (!item.name || item.name.length < 2) {
  errors.push("NAME_TOO_SHORT");
}

const isValid = errors.length === 0;

return {
  json: {
    ...item,
    isValid: isValid,
    validationErrors: errors
  }
};

return {
  json: {
    quarantineType: "SYNTAX_OR_SPAM_VIOLATION",
    leadId: $json.leadId,
    email: $json.email,
    reasons: $json.validationErrors,
    quarantinedAt: new Date().toISOString()
  }
};

const items = $input.all();
const seenEmails = new Set();
const seenPhones = new Set();
const results = [];

for (const entry of items) {
  const item = entry.json;
  let isDup = false;
  let dupReason = '';

  if (seenEmails.has(item.email)) {
    isDup = true;
    dupReason = `Duplicate Email: ${item.email}`;
  } else if (seenPhones.has(item.phone)) {
    isDup = true;
    dupReason = `Duplicate Phone: ${item.phone}`;
  } else {
    seenEmails.add(item.email);
    seenPhones.add(item.phone);
  }

  results.push({
    json: {
      ...item,
      isDuplicate: isDup,
      duplicateReason: dupReason
    }
  });
}

return results;

return {
  json: {
    quarantineType: "DUPLICATE_RECORD_SUPPRESSED",
    leadId: $json.leadId,
    email: $json.email,
    phone: $json.phone,
    reason: $json.duplicateReason,
    quarantinedAt: new Date().toISOString()
  }
};

const syncedLeads = $input.all();
return [
  {
    json: {
      status: "LEAD_CLEANSING_BATCH_COMPLETE",
      leadsSentToCRM: syncedLeads.length,
      leadRecords: syncedLeads.map(l => {
        const itemData = l.json.json || l.json;
        return {
          crmLeadId: itemData.leadId || "CRM_SYNCED",
          email: itemData.email,
          phone: itemData.phone
        };
      }),
      timestamp: new Date().toISOString()
    }
  }
];
